"""Synthetic MPT fixtures generated by HexaryTrie, plus captured evidence mutations.

Synthetic proofs test the verifier; none are historical Robinhood evidence.
"""
import copy
import json
from pathlib import Path
import sys
import tempfile
import unittest
import urllib.error
from unittest.mock import Mock

import rlp
from trie import HexaryTrie

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'src'))
import verify as v
import intake
import audit


def fixture(address, values, requested=None, code=b'\x60\x00', absent=False):
    """Independent library creates both tries and every proof path."""
    storage = HexaryTrie(db={})
    for key, value in values.items():
        if value:
            storage[v.k256(key.to_bytes(32, 'big'))] = rlp.encode(value)
    accounts = HexaryTrie(db={})
    account_key = v.k256(bytes.fromhex(address[2:]))
    if not absent:
        accounts[account_key] = rlp.encode([1, 123, storage.root_hash, v.k256(code)])
    keys = list(values) if requested is None else requested
    proof = {'address': address, 'nonce': '0x0' if absent else '0x1',
             'balance': '0x0' if absent else '0x7b',
             'storageHash': '0x' + storage.root_hash.hex(),
             'codeHash': '0x' + v.k256(b'' if absent else code).hex(),
             'accountProof': ['0x' + rlp.encode(n).hex() for n in accounts.get_proof(account_key)],
             'storageProof': []}
    for key in keys:
        proof['storageProof'].append({'key': hex(key), 'value': hex(values.get(key, 0)),
            'proof': ['0x' + rlp.encode(n).hex() for n in storage.get_proof(v.k256(key.to_bytes(32, 'big')))]})
    return '0x' + accounts.root_hash.hex(), proof, '0x' + code.hex()


def independent_header_hash(header):
    fields = ['parentHash', 'sha3Uncles', 'miner', 'stateRoot', 'transactionsRoot',
              'receiptsRoot', 'logsBloom', 'difficulty', 'number', 'gasLimit',
              'gasUsed', 'timestamp', 'extraData', 'mixHash', 'nonce', 'baseFeePerGas']
    numbers = {'difficulty', 'number', 'gasLimit', 'gasUsed', 'timestamp', 'baseFeePerGas'}
    encoded = [int(header[k], 16) if k in numbers else bytes.fromhex(header[k][2:]) for k in fields]
    return '0x' + v.k256(rlp.encode(encoded)).hex()


def history_fixture(code=v.HISTORY_CODE):
    target = v.read_json(ROOT / 'inputs/target-header.json')['result']
    parent = v.read_json(ROOT / 'inputs/parent-header.json')['result']
    values = {v.TARGET_NUMBER % v.HISTORY_WINDOW: int(target['hash'], 16),
              v.PARENT_NUMBER % v.HISTORY_WINDOW: int(parent['hash'], 16)}
    root, proof, encoded_code = fixture(v.HISTORY_ADDRESS, values, code=code)
    anchor = copy.deepcopy(target)
    anchor.update(number=hex(v.ANCHOR_NUMBER), stateRoot=root)
    anchor['hash'] = independent_header_hash(anchor)
    return anchor, target, parent, proof, encoded_code


class ProofTests(unittest.TestCase):
    def setUp(self):
        self.slots = [9, 13, 15, 17]
        self.root, self.proof, self.code = fixture(v.PRIORITY_ADDRESS, {9: 101, 13: 202, 15: 303}, requested=self.slots)

    def check(self, **overrides):
        args = dict(root=self.root, address=v.PRIORITY_ADDRESS,
                    slots=[v.slot(s) for s in self.slots], proof=self.proof, code=self.code)
        args.update(overrides)
        return v.account_proof(**args)

    def test_membership_and_proven_absence(self):
        result = self.check()
        self.assertEqual(result['storage_values'][v.slot(9)], '101')
        self.assertEqual(result['storage_values'][v.slot(17)], '0')
        self.assertFalse(result['historical_position_authenticated'])

    def test_wrong_root_address_and_code(self):
        for change in [{'root': '0x' + '12' * 32}, {'address': '0x' + '34' * 20}, {'code': '0x01'}]:
            with self.subTest(change=change), self.assertRaises(ValueError):
                self.check(**change)

    def test_declared_value_and_account_tampering(self):
        for mutation in ['balance', 'nonce', 'storageHash', 'codeHash', 'value']:
            proof = copy.deepcopy(self.proof)
            if mutation == 'value':
                proof['storageProof'][0]['value'] = '0x0'
            else:
                proof[mutation] = '0x0' if mutation in ['balance', 'nonce'] else '0x' + '11' * 32
            with self.subTest(mutation=mutation), self.assertRaises(ValueError):
                self.check(proof=proof)

    def test_missing_storage_not_filled_with_zero(self):
        proof = copy.deepcopy(self.proof)
        proof['storageProof'].pop()
        with self.assertRaisesRegex(ValueError, 'Missing or extra'):
            self.check(proof=proof)

    def test_duplicate_or_extra_slots_rejected(self):
        for duplicate in [True, False]:
            proof = copy.deepcopy(self.proof)
            entry = copy.deepcopy(proof['storageProof'][0])
            if not duplicate:
                entry['key'] = '0x22'
            proof['storageProof'].append(entry)
            with self.subTest(duplicate=duplicate), self.assertRaises(ValueError):
                self.check(proof=proof)

    def test_incomplete_or_mutated_path_rejected(self):
        for missing in [True, False]:
            proof = copy.deepcopy(self.proof)
            if missing:
                proof['storageProof'][0]['proof'] = []
            else:
                raw = bytearray.fromhex(proof['accountProof'][0][2:])
                raw[-1] ^= 1
                proof['accountProof'][0] = '0x' + raw.hex()
            with self.subTest(missing=missing), self.assertRaises(ValueError):
                self.check(proof=proof)

    def test_zero_requires_noninclusion_proof(self):
        proof = copy.deepcopy(self.proof)
        proof['storageProof'][-1]['proof'] = []
        with self.assertRaises(ValueError):
            self.check(proof=proof)

    def test_empty_storage_and_absent_account(self):
        root, proof, _ = fixture(v.PRIORITY_ADDRESS, {}, requested=[9], code=b'', absent=True)
        result = v.account_proof(root, v.PRIORITY_ADDRESS, [v.slot(9)], proof, '0x')
        self.assertEqual(result['storage_values'][v.slot(9)], '0')
        self.assertFalse(result['commercial_admission'])

    def test_noncanonical_quantities_rejected(self):
        for value in ['0x00', '0x', '-0x1', '1', '0x' + 'f' * 65, True]:
            proof = copy.deepcopy(self.proof)
            proof['nonce'] = value
            with self.subTest(value=value), self.assertRaises(ValueError):
                self.check(proof=proof)

    def test_padded_and_quantity_slot_encodings_agree(self):
        proof = copy.deepcopy(self.proof)
        for entry in proof['storageProof']:
            entry['key'] = v.slot(int(entry['key'], 16))
        self.assertEqual(self.check(), self.check(proof=proof))


class HistoryAndHeaderTests(unittest.TestCase):
    def test_real_captured_header_hashes(self):
        for name, expected in [('target', v.TARGET_HASH), ('parent', v.PARENT_HASH)]:
            header = v.read_json(ROOT / f'inputs/{name}-header.json')['result']
            self.assertEqual(v.validate_header(header, expected), expected)

    def test_modified_header_state_and_metadata_rejected(self):
        header = v.read_json(ROOT / 'inputs/target-header.json')['result']
        for field in ['stateRoot', 'sendRoot', 'sendCount', 'l1BlockNumber', 'withdrawalsRoot']:
            modified = copy.deepcopy(header)
            modified[field] = '0x0' if field in ['sendCount', 'l1BlockNumber'] else '0x' + '12' * 32
            with self.subTest(field=field), self.assertRaises(ValueError):
                v.validate_header(modified, v.TARGET_HASH)

    def test_synthetic_history_bridge_never_authenticates_consensus(self):
        anchor, target, parent, proof, code = history_fixture()
        result = v.history_bridge(anchor, target, parent, proof, code, anchor['hash'])
        self.assertEqual(result['block_distances'], [9256, 9257])
        self.assertFalse(result['canonical_anchor_authenticated'])
        self.assertFalse(result['exact_pretransaction_state_authenticated'])

    def test_observed_anchor_hash_cannot_be_replaced_by_synthetic(self):
        with self.assertRaisesRegex(ValueError, 'Unexpected block hash'):
            v.history_bridge(*history_fixture())

    def test_wrong_ethereum_history_runtime_rejected(self):
        ethereum = bytes.fromhex('3373fffffffffffffffffffffffffffffffffffffffe14604657602036036042575f35600143038111604257611fff81430311604257611fff9006545f5260205ff35b5f5ffd5b5f35611fff60014303065500')
        anchor, target, parent, proof, code = history_fixture(ethereum)
        with self.assertRaisesRegex(ValueError, 'Wrong history contract runtime'):
            v.history_bridge(anchor, target, parent, proof, code, anchor['hash'])

    def test_ring_window_boundaries(self):
        anchor, target, parent, proof, code = history_fixture()
        for distance, accepted in [(1, True), (v.HISTORY_WINDOW - 1, True), (v.HISTORY_WINDOW, False), (0, False)]:
            # Both target and parent must fit. The parent is one block older.
            modified = copy.deepcopy(anchor)
            modified['number'] = hex(v.TARGET_NUMBER + distance)
            modified['hash'] = independent_header_hash(modified)
            if accepted:
                v.history_bridge(modified, target, parent, proof, code, modified['hash'])
            else:
                with self.subTest(distance=distance), self.assertRaises(ValueError):
                    v.history_bridge(modified, target, parent, proof, code, modified['hash'])

    def test_wrong_history_hash_value_rejected(self):
        anchor, target, parent, _, code = history_fixture()
        values = {v.TARGET_NUMBER % v.HISTORY_WINDOW: 1, v.PARENT_NUMBER % v.HISTORY_WINDOW: int(parent['hash'], 16)}
        root, proof, _ = fixture(v.HISTORY_ADDRESS, values, code=v.HISTORY_CODE)
        anchor['stateRoot'] = root
        anchor['hash'] = independent_header_hash(anchor)
        with self.assertRaisesRegex(ValueError, 'History hash mismatch'):
            v.history_bridge(anchor, target, parent, proof, code, anchor['hash'])

    def test_wrong_ethereum_modulus_slots_rejected(self):
        anchor, target, parent, proof, code = history_fixture()
        proof['storageProof'][0]['key'] = hex(v.TARGET_NUMBER % 8191)
        with self.assertRaisesRegex(ValueError, 'Missing or extra'):
            v.history_bridge(anchor, target, parent, proof, code, anchor['hash'])

    def test_arbos_page_mapping_not_flat_offsets(self):
        mapped = [v.arbos_slot(n) for n in [0, 1, 2, 4, 5, 255, 256]]
        self.assertEqual(mapped[0], '0x15fed0451499512d95f3ec5a41c878b9de55f21878b5b4e190d4667ec709b400')
        self.assertEqual(len(set(mapped)), 7)
        self.assertEqual(len(set(x[:-2] for x in mapped[:6])), 1)
        self.assertNotEqual(mapped[0][:-2], mapped[-1][:-2])
        self.assertNotEqual(v.arbos_slot(0), v.slot(0))


class IntakeAndEvidenceTests(unittest.TestCase):
    def test_fixed_requests_use_exact_hashes_and_canonical_selector(self):
        rows = intake.plan()
        self.assertEqual(len(rows), 8)
        self.assertEqual([r['request']['id'] for r in rows], list(range(1, 9)))
        for row in rows:
            req = row['request']
            if req['method'] in ['eth_getProof', 'eth_getCode']:
                self.assertEqual(set(req['params'][-1]), {'blockHash', 'requireCanonical'})
                self.assertIs(req['params'][-1]['requireCanonical'], True)
        self.assertNotIn('latest', json.dumps(rows))

    def test_rpc_envelope_rejections(self):
        for response in [{'jsonrpc': '2.0', 'id': True, 'result': '0x1237'},
                         {'jsonrpc': '2.0', 'id': 2, 'result': '0x1237'},
                         {'jsonrpc': '2.0', 'id': 1, 'result': None},
                         {'jsonrpc': '2.0', 'id': 1, 'error': {'code': -32602}, 'result': '0x1237'}]:
            with self.subTest(response=response), self.assertRaises(ValueError):
                intake.envelope(response, 1)

    def test_duplicate_json_keys_and_byte_limit(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'input.json'
            path.write_text('{"result": 1, "result": 2}')
            with self.assertRaisesRegex(ValueError, 'Duplicate JSON key'):
                v.read_json(path)
            with self.assertRaisesRegex(ValueError, 'byte limit'):
                v.read_json(path, limit=4)

    def test_failed_proof_stops_before_code_or_anchor_requests(self):
        calls = []
        def fetch(operation):
            req = operation['request']
            calls.append(req['id'])
            results = {1: '0x1237', 2: v.read_json(ROOT / 'inputs/parent-header.json')['result'],
                       3: {'address': v.PRIORITY_ADDRESS, 'nonce': '0x1', 'balance': '0x0', 'storageProof': []}}
            return {'jsonrpc': '2.0', 'id': req['id'], 'result': results[req['id']]}
        with tempfile.TemporaryDirectory() as tmp:
            report = intake.execute(fetch, Path(tmp) / 'output')
            self.assertEqual(calls, [1, 2, 3])
            self.assertEqual(report['responses_verified'], 2)
            self.assertEqual(report['failed_purpose'], 'priority_proof')
            self.assertEqual(report['status'], 'BLOCKED_OR_REJECTED')
            self.assertFalse(report['gates']['commercial_admission'])
            self.assertTrue((Path(tmp) / 'output/03-priority_proof.json').is_file())

    def test_missing_export_does_not_generate_proofs(self):
        with tempfile.TemporaryDirectory() as tmp:
            report = intake.execute(lambda op: v.read_json(Path(tmp) / 'absent.json'), Path(tmp) / 'out')
            self.assertEqual(report['responses_verified'], 0)
            self.assertFalse(report['gates']['parent_witness_complete'])

    def test_403_has_no_retry_or_secret_in_error(self):
        transport = intake.Transport('https://example.invalid/private-secret')
        transport.opener = Mock()
        transport.opener.open.side_effect = urllib.error.HTTPError('https://example.invalid/private-secret', 403, 'private-secret', {}, None)
        with self.assertRaisesRegex(ValueError, 'HTTP 403; no retry') as raised:
            transport(intake.plan()[0]['request'])
        self.assertEqual(transport.opener.open.call_count, 1)
        self.assertNotIn('private-secret', str(raised.exception))

    def test_transport_refuses_unapproved_request_before_network(self):
        transport = intake.Transport('https://example.invalid')
        transport.opener = Mock()
        for request in [{'method': 'eth_sendRawTransaction', 'params': ['0x00']},
                        {'jsonrpc': '2.0', 'id': 2, 'method': 'eth_getBlockByHash', 'params': ['latest', False]}]:
            with self.assertRaisesRegex(ValueError, 'Unapproved request'):
                transport(request)
        transport.opener.open.assert_not_called()

    def test_redirect_refused(self):
        with self.assertRaisesRegex(ValueError, 'Redirect refused'):
            intake.NoRedirect().redirect_request(None, None, 302, '', {}, 'https://example.invalid')

    def test_endpoint_validation(self):
        for endpoint in ['http://example.com', 'https://user:password@example.com', 'file:///tmp/state', 'https://example.com/#fragment']:
            with self.subTest(endpoint=endpoint), self.assertRaises(ValueError):
                intake.Transport(endpoint)

    def test_actual_confirmation_log_raw_decode(self):
        observation = v.read_json(ROOT / 'inputs/l1-observations.json')['confirmation']
        logs = v.read_json(ROOT / 'evidence/blockscout-confirmation-logs.json')
        result = audit.confirmation_event(logs, observation)
        self.assertTrue(result['raw_event_fields_match'])
        self.assertFalse(result['receipt_inclusion_verified'])

    def test_diagnostic_system_accounts_present_but_context_incomplete(self):
        previous = v.read_json(ROOT / 'inputs/augmented-prestate.json')['result']
        self.assertIn(v.ARBOS_ADDRESS, previous)
        self.assertIn(v.HISTORY_ADDRESS, previous)
        self.assertEqual(len(previous[v.ARBOS_ADDRESS]['storage']), 15)
        self.assertEqual(v.data_hex(previous[v.HISTORY_ADDRESS]['code']), v.HISTORY_CODE)
        missing = {name for name, offset in v.ARBOS_FIELDS.items()
                   if v.arbos_slot(offset) not in previous[v.ARBOS_ADDRESS]['storage']}
        self.assertEqual(missing, {'upgrade_version', 'upgrade_timestamp', 'chain_id', 'genesis_block_number'})
        self.assertNotIn('accountProof', previous[v.ARBOS_ADDRESS])

    def test_decoded_event_does_not_override_mutated_raw_fields(self):
        observation = v.read_json(ROOT / 'inputs/l1-observations.json')['confirmation']
        original = v.read_json(ROOT / 'evidence/blockscout-confirmation-logs.json')
        for mutation in ['address', 'data', 'data_truncated', 'block_number']:
            logs = copy.deepcopy(original)
            row = logs['structuredContent']['data'][1]
            row[mutation] = {'address': '0x' + '01' * 20, 'data': '0x' + '00' * 64,
                             'data_truncated': True, 'block_number': 1}[mutation]
            with self.subTest(mutation=mutation), self.assertRaises(ValueError):
                audit.confirmation_event(logs, observation)

    def test_successful_relative_checks_leave_all_admission_gates_closed(self):
        expected = v.read_json(ROOT / 'inputs/TARGET.json')['priority_slots']
        state = {'priority_checked': {'storage_values': {x['slot']: str(int(x['expected_event_derived_value'], 16)) for x in expected}},
                 'arbos_checked': {'version': 61}, 'history_checked': {'canonical_anchor_authenticated': False}}
        state['priority_checked']['storage_values'][expected[0]['slot']] = '0'
        result = intake.result_report(state)
        self.assertFalse(result['event_comparisons'][0]['equal_to_event_derived_value'])
        self.assertEqual(result['gates']['authenticated_pretransaction_priority_slots'], 0)
        self.assertIsNone(result['gates']['exact_prestate_root'])
        self.assertFalse(result['gates']['commercial_admission'])


if __name__ == '__main__':
    unittest.main()
